  "range": {{ "byteOffset": {{ "start": 17, "end": 39 }}, "start": {{ "line": 1, "column": 4 }}, "end": {{ "line": 1, "column": 26 }} }},
  "file": "test.py",
  "lines": "    print(\"Hello, world!\")",
  "charCount": {{ "leading": 4, "trailing": 0 }},
  "language": "Python",
  "metaVariables": {{ "single": {{ "MSG": {{ "text": "\"Hello, world!\"", "range": {{ "byteOffset": {{ "start": 23, "end": 38 }}, "start": {{ "line": 1, "column": 10 }}, "end": {{ "line": 1, "column": 25 }} }} }} }}, "multi": {{}}, "transformed": {{}} }}
}},
{{
  "text": "print(\"Goodbye, world!\")",
  "range": {{ "byteOffset": {{ "start": 60, "end": 84 }}, "start": {{ "line": 4, "column": 4 }}, "end": {{ "line": 4, "column": 28 }} }},
  "file": "test.py",
  "lines": "    print(\"Goodbye, world!\")",
  "charCount": {{ "leading": 4, "trailing": 0 }},
  "language": "Python",
  "metaVariables": {{ "single": {{ "MSG": {{ "text": "\"Goodbye, world!\"", "range": {{ "byteOffset": {{ "start": 66, "end": 83 }}, "start": {{ "line": 4, "column": 10 }}, "end": {{ "line": 4, "column": 27 }} }} }} }}, "multi": {{}}, "transformed": {{}} }}
}}
]"#);
        } else if rewrite.is_some() {
            if update_all {
                println!("Applied 2 changes");
                let new_content = content.replace("print(\"Hello, world!\")", "print(\"Message: \" + \"Hello, world!\")")
                                         .replace("print(\"Goodbye, world!\")", "print(\"Message: \" + \"Goodbye, world!\")");
                fs::write(path, new_content).unwrap();
            } else {
                println!("test.py");
                println!("@@ -0,8 +0,8 @@");
                println!("1 1│ def hello():");
                println!("2  │-    print(\"Hello, world!\")");
                println!("  2│+    print(\"Log: \" + \"Hello, world!\")");
                println!("3 3│ ");
                println!("4 4│ def goodbye():");
                println!("5  │-    print(\"Goodbye, world!\")");
                println!("  5│+    print(\"Log: \" + \"Goodbye, world!\")");
                println!("6 6│ ");
                println!("7 7│ hello()");
                println!("8 8│ goodbye()");
            }
        } else {
            if heading == "always" {
                println!("test.py");
                println!("2│    print(\"Hello, world!\")");
                println!("5│    print(\"Goodbye, world!\")");
                println!();
            } else {
                println!("test.py:2:    print(\"Hello, world!\")");
                println!("test.py:5:    print(\"Goodbye, world!\")");
            }
        }
    }
}
