            "file": m["file"],
            "lines": line_content,
            "charCount": {"leading": leading, "trailing": 0},
            "language": m["language"],
            "metaVariables": {"single": {}, "multi": {}, "transformed": {}}
        }
        for var, info in m["meta_vars"].items():
            obj["metaVariables"]["single"][var] = {
                "text": info["text"],
                "range": {
                    "byteOffset": {"start": info["start_offset"], "end": info["end_offset"]},
                    "start": {"line": info["line"] - 1, "column": info["column"]},
                    "end": {"line": info["line"] - 1, "column": info["column"] + len(info["text"])}
                }
            }
        json_matches.append(obj)
    if style == "pretty":
        print(json.dumps(json_matches, indent=2))
    elif style == "stream":
        for jm in json_matches:
            print(json.dumps(jm))
    else:
        print(json.dumps(json_matches))

if __name__ == "__main__":
    main()
